typedef unsigned int size_t;

extern "C" void *memmove(void *, const void *, unsigned int);
extern "C" void *arch_malloc(unsigned int, const char *, int);
extern "C" void arch_free(void *);

template<int inst>
class __malloc_alloc_template
{
public:
  static void *_S_oom_malloc(size_t);

  static void *allocate(size_t n)
  {
    void *result = arch_malloc(n, __FILE__, 0);
    if (result == 0)
      result = _S_oom_malloc(n);
    return result;
  }

  static void deallocate(void *p, size_t)
  {
    arch_free(p);
  }
};

template<bool threads, int inst>
class __my_default_alloc_template
{
  union obj
  {
    obj *free_list_link;
    char data[1];
  };

  enum { ALIGN = 8, MAX_BYTES = 128, NFREELISTS = 16 };

public:
  static obj *free_list[NFREELISTS];
  static void *refill(size_t);

  static size_t freelist_index(size_t bytes)
  {
    return (bytes + ALIGN - 1) / ALIGN - 1;
  }

  static void *allocate(size_t n)
  {
    if (n > MAX_BYTES)
      return __malloc_alloc_template<inst>::allocate(n);

    obj **list = free_list + freelist_index(n);
    obj *result = *list;
    if (result == 0)
      return refill(n);
    *list = result->free_list_link;
    return result;
  }

  static void deallocate(void *p, size_t n)
  {
    if (n > MAX_BYTES)
    {
      __malloc_alloc_template<inst>::deallocate(p, n);
      return;
    }

    obj **list = free_list + freelist_index(n);
    obj *node = (obj *)p;
    node->free_list_link = *list;
    *list = node;
  }
};

template<class T>
class my_allocator
{
public:
  static T *allocate(size_t n)
  {
    return n
      ? (T *)__my_default_alloc_template<false, 0>::allocate(n * sizeof(T))
      : 0;
  }

  static void deallocate(T *p, size_t n)
  {
    if (p)
      __my_default_alloc_template<false, 0>::deallocate(
        p, n * sizeof(T));
  }
};

template<class T>
inline T *copy(const T *first, const T *last, T *result)
{
  memmove(result, first, sizeof(T) * (last - first));
  return result + (last - first);
}

template<class T>
inline T *uninitialized_copy(const T *first, const T *last, T *result)
{
  return copy(first, last, result);
}

template<class T>
inline void destroy(T *, T *)
{
}

template<class T, class Alloc>
class vector
{
protected:
  T *start_;
  T *finish_;
  T *end_of_storage_;

  T *allocate(size_t n)
  {
    return Alloc::allocate(n);
  }

  void deallocate(T *p, size_t n)
  {
    Alloc::deallocate(p, n);
  }

public:
  typedef T *iterator;
  typedef const T *const_iterator;
  typedef size_t size_type;

  iterator begin() { return start_; }
  const_iterator begin() const { return start_; }
  iterator end() { return finish_; }
  const_iterator end() const { return finish_; }
  size_type size() const { return finish_ - start_; }
  size_type capacity() const { return end_of_storage_ - start_; }

  iterator allocate_and_copy(
    size_type n, const_iterator first, const_iterator last)
  {
    iterator result = allocate(n);
    uninitialized_copy(first, last, result);
    return result;
  }

  vector<T, Alloc> &operator=(const vector<T, Alloc> &x);
};

template<class T, class Alloc>
vector<T, Alloc> &
vector<T, Alloc>::operator=(const vector<T, Alloc> &x)
{
  if (&x != this)
  {
    const size_type xlen = x.size();
    if (xlen > capacity())
    {
      iterator tmp = allocate_and_copy(xlen, x.begin(), x.end());
      destroy(start_, finish_);
      deallocate(start_, end_of_storage_ - start_);
      start_ = tmp;
      end_of_storage_ = start_ + xlen;
    }
    else if (size() >= xlen)
    {
      iterator i = copy(x.begin(), x.end(), begin());
      destroy(i, finish_);
    }
    else
    {
      copy(x.begin(), x.begin() + size(), start_);
      uninitialized_copy(x.begin() + size(), x.end(), finish_);
    }
    finish_ = start_ + xlen;
  }
  return *this;
}

template vector<char, my_allocator<char> > &
vector<char, my_allocator<char> >::operator=(
  const vector<char, my_allocator<char> > &);
